    errorClass = 'API_TRANSIENT';
    retryable = true;
  }
  return {
    stage: stage || 'UNKNOWN',
    error_class: errorClass,
    retryable,
    http_code: code,
    message: truncate(scrubSecrets(message), 1500),
  };
}

